/**
 * Page Header provides a title and other optional information for a content section or page.
 *
 *
 * ### Features
 *
 * Page Header has main title for the page as well as it also provides options such as Breadcrumb, ButtonGroup, Description, TagGroup and Tab Navigation.
 *
 * ```tsx
 * const [isOpen, setIsOpen] = React.useState(false);
 *
 * <PageHeader
 *      breadcrumb={[
 *          {
 *           label: 'breadcrumb 1',
 *           href: '',
 *           isCurrent: true,
 *         },
 *         { label: 'breadcrumb 2', href: '' },
 *       ]}
 *       headerDropdown={true}
 *       keyCTAsButtonGroup={[
 *         <Button variant="tertiary">Button 1</Button>,
 *         <Button variant="secondary">Button 2</Button>,
 *         <Button variant="primary">Button 3</Button>,
 *         <IconButton a11yLabel="wallet-button"><Wallet /></IconButton>,
 *         <Chip>Chip</Chip>,
 *       ]}
 *       description="Lorem ipsum dolor sit amet, consectetur adipiscing elit."
 *       tagProps={[
 *         { label: 'Tag 1', tagVariant: 'primary' },
 *         { label: 'Tag 2', tagVariant: 'secondary' },
 *         { label: 'Tag 3', tagVariant: 'tertiary' },
 *       ]}
 *       tabNavigation={[
 *         {
 *           label: 'Tab 1',
 *           href: '',
 *           isCurrent: true,
 *           onClick: () => console.log('tab clicked');
 *         },
 *         {
 *           label: 'Tab 2',
 *           href: '',
 *           onClick: () => console.log('tab clicked');
 *         },
 *       ]},
 *       pageTitleActionsMenu: {
 *          isOpen: isOpen,
 *          refOnClick: () => setIsOpen(true),
 *          onClose: () => setIsOpen(false),
 *          textFieldProps: {
 *            label: 'Lorem ipsum',
 *            onChange: () => {},
 *            value: 'Lorem ipsum dolor sit amet consectetur',
 *            onKeyDown: () => {}
 *          },
 *          onClickOutside: () => {}
 *          actionsList: [
 *            { label: 'Lorem ipsum', handleClick: () => {}, leading: <Star /> },
 *            { label: 'Lorem ipsum', handleClick: () => {}, leading: <Star /> },
 *            { label: 'Lorem ipsum', handleClick: () => {}, leading: <Star /> },
 *          ],
 *        enableLastActionDivider: true,
 * >Page Title</PageHeader>
 * ```
 *
 * #### Breadcrumb
 * Set the values of breadcrumb prop with label, href, isCurrent, onClick, target properties.
 *
 * ```tsx
 * <PageHeader
 *      breadcrumb={[
 *          {label: 'breadcrumb 1', href: '', },
 *          {label: 'breadcrumb 2', href: '',
 *            target: 'Breadcrumb 2',
 *            isCurrent: true
              onClick: (event) => {
                  event.preventDefault();
                  console.log(event.currentTarget.getAttribute('target'));
              }, },
 *          ]}
 * >Page Title</PageHeader>
 * ```
 *
 * #### Page Title Button
 * Set the value of children as the content of the page title, and set headerDropdown to true or false to show the down arrow.
 *
 * ```tsx
 * <PageHeader
 *      headerDropdown={true}
 * >Page Title</PageHeader>
 * ```
 *
 * #### Button Group
 * Set the values for ButtonGroup using keyCTAsButtonGroup prop. You can pass buttons, icon buttons or chips in the array.
 *
 * ```tsx
 * <PageHeader
 *      keyCTAsButtonGroup= {[
 *          <Button variant="tertiary">Button 1</Button>,
 *          <Button variant="secondary">Button 2</Button>,
 *          <Button variant="primary">Button 3</Button>,
 *          <IconButton a11yLabel="wallet-button"><Wallet /></IconButton>,
 *          <Chip>Chip</Chip>,
 *       ]}
 * >Page Title</PageHeader>
 * ```
 *
 * #### Description
 * Description can be passed using description prop.
 *
 * ```tsx
 * <PageHeader
 *      description="Lorem ipsum dolor sit amet consectetur. Magna nunc nulla et eleifend ac vel. Varius pellentesque massa a volutpat pharetra malesuada malesuada sit. Laoreet lorem tristique egestas iaculis. Nisi eget in varius velit leo enim felis non tellus. Ipsum turpis rhoncus ipsum interdum ullamcorper morbi dui eget varius."
 * >Page Title</PageHeader>
 * ```
 *
 * #### Tag Group
 * Set the values for TagGroup using tagProps prop. You can set the label for tag and variant using label and variant properties.
 *
 * ```tsx
 * <PageHeader
 *      tagProps={[{ label: 'Tag 1', tagVariant: 'primary' },
 *           { label: 'Tag 2', tagVariant: 'secondary' },
 *           { label: 'Tag 3', tagVariant: 'tertiary' },]}
 * >Page Title</PageHeader>
 * ```
 *
 * #### Tab Navigation
 * Set the values for TabNavigation using tagNavigation prop. You can pass label, href, isCurrent and onClick properties for each prop.
 *
 * ```tsx
 * <PageHeader
 *      tabNavigation={[{label: 'Tab 1', href:'', isCurrent:true, onClick: () => console.log('tab clicked');}, {label: 'Tab 2', href:'', onClick: () => console.log('tab clicked');}]}
 * >Page Title</PageHeader>
 * ```
 *
 * #### Page Title Actions Menu
 *  PageHeader provides pageTitleActionsMenu, which consists of TextField and a list of action buttons.
 *  The intended use of TextField is to let the consumer rename the page title using the exposed props.
 * - Set the values of props for TextField using `textFieldProps`, textFieldProps has following props:
 *  - label
 *  - onChange
 *  - value
 *  - onKeyDown
 *  - error (optional)
 * - The intended use of `actionsList` is to provide a list of page level actions that the user can take.
 * - Set the values of list of action buttons using actionsList, actionsList has following props:
 *  - label
 *  - handleClick
 *  - leading (optional)
 * - The intented use of `refOnClick` is to pass a function to open the Popover on clicking the ref Button or Chip.
 * - Pass the variable to `isOpen` that stores the open or closed state for Popover.
 * - Pass the function to `onClose` to close the Popover.
 * - The intended use of `onClickOutside` is to use it alongside `textFieldProps` to trigger change in the page title, when user clicks outside the popover.
 * - Set the value of `enableLastActionDivider` prop to true or false, to toggle a divider before the last action item in the list.
 *
 * ```tsx
 * const [isOpen, setIsOpen] = React.useState(false);
 *
 * <PageHeader
 *    pageTitleActionsMenu: {
 *          isOpen: isOpen,
 *          refOnClick: () => setIsOpen(true),
 *          onClose: () => setIsOpen(false),
 *          textFieldProps: {
 *            label: 'Lorem ipsum',
 *            onChange: () => {},
 *            value: 'Lorem ipsum dolor sit amet consectetur',
 *            onKeyDown: () => {}
 *          },
 *          onClickOutside: () => {}
 *          actionsList: [
 *            { label: 'Lorem ipsum', handleClick: () => {}, leading: <Star /> },
 *            { label: 'Lorem ipsum', handleClick: () => {}, leading: <Star /> },
 *            { label: 'Lorem ipsum', handleClick: () => {}, leading: <Star /> },
 *          ],
 *        enableLastActionDivider: true,
 * }>Page Title</PageHeader>
 * ```
 *
 */
export declare const PageHeader: React.FC<PageHeaderProps>;
